#include "sio_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

SInt16 sio_tx_unsigned (Sio sio , UInt32 unum , UInt8 base , UInt8 digits)
{
  return sio_tx_unsigned_t (sio , unum , base , digits , 0) ;
}

//--------------------------------------------------------------------------//

SInt16 sio_tx_unsigned_t (Sio sio , UInt32 unum , UInt8 base , UInt8 digits , Sio_Timeout timeout)
{
  SInt16 sio_status = SIO_DOMAIN ;

  if (2 <= base && base <= 16)
    {
      UInt8   stack    [32] ;
      UInt8   stack_sp = 0  ;

      Boolean is_fixed_width = !! digits ;

      for (;;)
        {
          stack [stack_sp++] = (UInt8) (unum % base) ; unum /= base ;

          if (is_fixed_width)
            {
              if (0 == --digits) break ;
            }
          else
            {
              if (0 == unum)     break ;
            }
        }

      do
        {
          static HVA_Const_Char_P hexmap = "0123456789ABCDEF" ;

          sio_status = sio_tx_t (sio , hexmap [stack [--stack_sp]] , timeout) ;
        }
      while (sio_status == SIO_OK && stack_sp != 0) ;
    }

  return sio_status ;
}

